-- Phase 4: licensing, product updates, coupons, wishlists, and reviews.
CREATE TYPE "LicenseStatus" AS ENUM ('ACTIVE', 'REVOKED');
CREATE TYPE "CouponType" AS ENUM ('FIXED', 'PERCENTAGE');
CREATE TYPE "ReviewStatus" AS ENUM ('ACTIVE', 'HIDDEN');
CREATE TYPE "ReportStatus" AS ENUM ('OPEN', 'RESOLVED');
CREATE TYPE "ProductVersionStatus" AS ENUM ('DRAFT', 'PUBLISHED');

ALTER TABLE "CartItem" ADD COLUMN "licenseTypeId" UUID;
ALTER TABLE "Order" ADD COLUMN "couponId" TEXT, ADD COLUMN "couponCode" TEXT, ADD COLUMN "discountMmk" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "OrderItem" ADD COLUMN "licenseTypeId" UUID, ADD COLUMN "licenseTypeCode" TEXT, ADD COLUMN "licensePriceMmk" INTEGER, ADD COLUMN "licenseTermsSnapshot" TEXT, ADD COLUMN "licenseAllowedUsageSnapshot" TEXT;

CREATE TABLE "ProductLicenseType" ("id" UUID NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "defaultTerms" TEXT NOT NULL, "defaultAllowedUsage" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ProductLicenseType_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProductLicensePrice" ("id" UUID NOT NULL, "productId" UUID NOT NULL, "licenseTypeId" UUID NOT NULL, "priceMmk" INTEGER NOT NULL, "licenseTerms" TEXT NOT NULL, "allowedUsage" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ProductLicensePrice_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CustomerLicense" ("id" UUID NOT NULL, "productId" UUID NOT NULL, "licenseTypeId" UUID NOT NULL, "orderId" UUID NOT NULL, "orderItemId" UUID NOT NULL, "customerId" UUID NOT NULL, "priceMmk" INTEGER NOT NULL, "licenseTerms" TEXT NOT NULL, "allowedUsage" TEXT NOT NULL, "licenseKey" TEXT NOT NULL, "status" "LicenseStatus" NOT NULL DEFAULT 'ACTIVE', "issuedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "revokedAt" TIMESTAMP(3), "revocationReason" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CustomerLicense_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProductVersion" ("id" UUID NOT NULL, "productId" UUID NOT NULL, "versionNumber" TEXT NOT NULL, "changelog" TEXT NOT NULL, "releaseNotes" TEXT, "releaseDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "status" "ProductVersionStatus" NOT NULL DEFAULT 'DRAFT', "updatePolicy" TEXT NOT NULL DEFAULT 'ACTIVE_LICENSE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ProductVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProductVersionFile" ("id" UUID NOT NULL, "versionId" UUID NOT NULL, "storageKey" TEXT NOT NULL, "fileSize" INTEGER NOT NULL, "checksum" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ProductVersionFile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Coupon" ("id" UUID NOT NULL, "code" TEXT NOT NULL, "type" "CouponType" NOT NULL, "amount" INTEGER NOT NULL, "startsAt" TIMESTAMP(3), "expiresAt" TIMESTAMP(3), "maxUsageCount" INTEGER, "perCustomerLimit" INTEGER, "minimumOrderMmk" INTEGER NOT NULL DEFAULT 0, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Coupon_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CouponProduct" ("couponId" UUID NOT NULL, "productId" UUID NOT NULL, CONSTRAINT "CouponProduct_pkey" PRIMARY KEY ("couponId", "productId"));
CREATE TABLE "CouponLicenseType" ("couponId" UUID NOT NULL, "licenseTypeId" UUID NOT NULL, CONSTRAINT "CouponLicenseType_pkey" PRIMARY KEY ("couponId", "licenseTypeId"));
CREATE TABLE "CouponRedemption" ("id" UUID NOT NULL, "couponId" UUID NOT NULL, "customerId" UUID NOT NULL, "orderId" UUID NOT NULL, "discountMmk" INTEGER NOT NULL, "redeemedAt" TIMESTAMP(3), "releasedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CouponRedemption_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WishlistItem" ("id" UUID NOT NULL, "customerId" UUID NOT NULL, "productId" UUID NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "WishlistItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProductReview" ("id" UUID NOT NULL, "productId" UUID NOT NULL, "customerId" UUID NOT NULL, "orderItemId" UUID NOT NULL, "rating" INTEGER NOT NULL, "title" TEXT NOT NULL, "content" TEXT NOT NULL, "status" "ReviewStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ProductReview_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReviewReport" ("id" UUID NOT NULL, "reviewId" UUID NOT NULL, "reporterId" UUID NOT NULL, "reason" TEXT NOT NULL, "status" "ReportStatus" NOT NULL DEFAULT 'OPEN', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "resolvedAt" TIMESTAMP(3), CONSTRAINT "ReviewReport_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "ProductLicenseType_code_key" ON "ProductLicenseType"("code");
CREATE UNIQUE INDEX "ProductLicensePrice_productId_licenseTypeId_key" ON "ProductLicensePrice"("productId","licenseTypeId"); CREATE INDEX "ProductLicensePrice_productId_isActive_idx" ON "ProductLicensePrice"("productId","isActive");
CREATE UNIQUE INDEX "CustomerLicense_orderItemId_key" ON "CustomerLicense"("orderItemId"); CREATE UNIQUE INDEX "CustomerLicense_licenseKey_key" ON "CustomerLicense"("licenseKey"); CREATE INDEX "CustomerLicense_customerId_status_createdAt_idx" ON "CustomerLicense"("customerId","status","createdAt"); CREATE INDEX "CustomerLicense_productId_status_idx" ON "CustomerLicense"("productId","status");
CREATE UNIQUE INDEX "ProductVersion_productId_versionNumber_key" ON "ProductVersion"("productId","versionNumber"); CREATE INDEX "ProductVersion_productId_status_releaseDate_idx" ON "ProductVersion"("productId","status","releaseDate"); CREATE UNIQUE INDEX "ProductVersionFile_versionId_key" ON "ProductVersionFile"("versionId");
CREATE UNIQUE INDEX "Coupon_code_key" ON "Coupon"("code"); CREATE INDEX "Coupon_isActive_startsAt_expiresAt_idx" ON "Coupon"("isActive","startsAt","expiresAt"); CREATE UNIQUE INDEX "CouponRedemption_orderId_key" ON "CouponRedemption"("orderId"); CREATE INDEX "CouponRedemption_couponId_redeemedAt_idx" ON "CouponRedemption"("couponId","redeemedAt"); CREATE INDEX "CouponRedemption_customerId_couponId_idx" ON "CouponRedemption"("customerId","couponId");
CREATE UNIQUE INDEX "WishlistItem_customerId_productId_key" ON "WishlistItem"("customerId","productId"); CREATE INDEX "WishlistItem_customerId_createdAt_idx" ON "WishlistItem"("customerId","createdAt"); CREATE UNIQUE INDEX "ProductReview_orderItemId_key" ON "ProductReview"("orderItemId"); CREATE UNIQUE INDEX "ProductReview_productId_customerId_key" ON "ProductReview"("productId","customerId"); CREATE INDEX "ProductReview_productId_status_createdAt_idx" ON "ProductReview"("productId","status","createdAt"); CREATE INDEX "ReviewReport_status_createdAt_idx" ON "ReviewReport"("status","createdAt");
CREATE INDEX "CartItem_licenseTypeId_idx" ON "CartItem"("licenseTypeId"); CREATE INDEX "OrderItem_licenseTypeId_idx" ON "OrderItem"("licenseTypeId");

ALTER TABLE "CartItem" ADD CONSTRAINT "CartItem_licenseTypeId_fkey" FOREIGN KEY ("licenseTypeId") REFERENCES "ProductLicenseType"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_licenseTypeId_fkey" FOREIGN KEY ("licenseTypeId") REFERENCES "ProductLicenseType"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ProductLicensePrice" ADD CONSTRAINT "ProductLicensePrice_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Template"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ProductLicensePrice" ADD CONSTRAINT "ProductLicensePrice_licenseTypeId_fkey" FOREIGN KEY ("licenseTypeId") REFERENCES "ProductLicenseType"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "CustomerLicense" ADD CONSTRAINT "CustomerLicense_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Template"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CustomerLicense" ADD CONSTRAINT "CustomerLicense_licenseTypeId_fkey" FOREIGN KEY ("licenseTypeId") REFERENCES "ProductLicenseType"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CustomerLicense" ADD CONSTRAINT "CustomerLicense_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CustomerLicense" ADD CONSTRAINT "CustomerLicense_orderItemId_fkey" FOREIGN KEY ("orderItemId") REFERENCES "OrderItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CustomerLicense" ADD CONSTRAINT "CustomerLicense_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ProductVersion" ADD CONSTRAINT "ProductVersion_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Template"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ProductVersionFile" ADD CONSTRAINT "ProductVersionFile_versionId_fkey" FOREIGN KEY ("versionId") REFERENCES "ProductVersion"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CouponProduct" ADD CONSTRAINT "CouponProduct_couponId_fkey" FOREIGN KEY ("couponId") REFERENCES "Coupon"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CouponProduct" ADD CONSTRAINT "CouponProduct_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Template"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CouponLicenseType" ADD CONSTRAINT "CouponLicenseType_couponId_fkey" FOREIGN KEY ("couponId") REFERENCES "Coupon"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CouponLicenseType" ADD CONSTRAINT "CouponLicenseType_licenseTypeId_fkey" FOREIGN KEY ("licenseTypeId") REFERENCES "ProductLicenseType"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CouponRedemption" ADD CONSTRAINT "CouponRedemption_couponId_fkey" FOREIGN KEY ("couponId") REFERENCES "Coupon"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CouponRedemption" ADD CONSTRAINT "CouponRedemption_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CouponRedemption" ADD CONSTRAINT "CouponRedemption_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WishlistItem" ADD CONSTRAINT "WishlistItem_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "WishlistItem" ADD CONSTRAINT "WishlistItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Template"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProductReview" ADD CONSTRAINT "ProductReview_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Template"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ProductReview" ADD CONSTRAINT "ProductReview_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ProductReview" ADD CONSTRAINT "ProductReview_orderItemId_fkey" FOREIGN KEY ("orderItemId") REFERENCES "OrderItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ReviewReport" ADD CONSTRAINT "ReviewReport_reviewId_fkey" FOREIGN KEY ("reviewId") REFERENCES "ProductReview"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ReviewReport" ADD CONSTRAINT "ReviewReport_reporterId_fkey" FOREIGN KEY ("reporterId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
